INSERT INTO popup.popup_content (popup_id, content_title, description, content_body, media_url, link_url, content_options, created_by, created_at, updated_by, updated_at) VALUES ('SAMPLE-TEXT-001', '서비스 일시 중단 안내', '시스템 정기 점검 안내입니다.', '2026년 정기 점검으로 일부 서비스 이용이 제한될 수 있습니다.', NULL, NULL, '{"emphasis": "점검 시간 동안 저장되지 않은 작업은 유실될 수 있습니다."}', 'SYSTEM', '2026-08-20 10:52:31.540049', 'SYSTEM', '2026-08-20 10:52:31.540049');
