INSERT INTO popup.popup_content (popup_id, content_title, description, content_body, media_url, link_url, content_options, created_by, created_at, updated_by, updated_at) VALUES ('TEXT-002', '교육 받아라', '신병왔다', '', NULL, '', '{"isLoop": false, "linkUrl": "", "autoPlay": false, "plainText": "", "imageWidth": 0, "description": "신병왔다", "imageHeight": 0, "contentTitle": "교육 받아라", "markdownMode": true, "showControls": true, "defaultVolume": 0.7, "highlightText": "", "imageSizeMode": "FIXED", "showHighlight": false, "showPlainText": true, "allowFullScreen": true, "leftSectionBody": "", "markdownContent": "# 정보보안 교육 안내\n\n## 교육 목적\n\n사내 정보와 개인정보를 **안전하게 보호**하기 위한 필수 교육입니다.\n\n### 주요 내용\n\n- 비밀번호를 다른 사람과 공유하지 마세요.\n- 의심스러운 링크는 클릭하지 마세요.\n- 자리를 비울 때 화면을 잠그세요.\n\n## 주의사항\n\n**교육 영상을 80% 이상 시청해야 완료됩니다.**\n\n`Windows + L` 키를 누르면 화면을 잠글 수 있습니다.", "showDescription": true, "showLeftSection": false, "leftSectionTitle": "", "rightSectionBody": "", "showRightSection": false, "bottomDescription": "", "rightSectionTitle": "", "showContentHeader": true, "additionalDescription": "", "showBottomDescription": false, "allowPlaybackRateChange": true}', 'master', '2026-08-20 15:02:24.547371', 'master', '2026-08-20 15:33:44.974116');
